1	/**
2	 * RAINBOW master course — ONE continuous route through the washer world.
3	 *
4	 * Units: 1 unit ≈ 5 cm at Benny's scale (Benny body radius ≈ 0.8). +Y is up (absolute altitude).
5	 * The route starts inside Drum A (scene 01/02), drains through a chute into the whirlpool basin (03),
6	 * drops down the five-arrow slide (04), winds through the perforated current tube (05), crests the
7	 * rinse arch (06), winds through the washer tube and then PLUNGES ~62 units straight down (07) before
8	 * the bottom of that same tube flares into the Final Spin Chamber inlet (08). 08–10 stay in that same
9	 * chamber; the route ends under the purple towel on the platform, where the 11 cinematic plays.
10	 *
11	 * Every stage is a range of arc-length `s` on a single centripetal Catmull-Rom spline, so position
12	 * and tangent are continuous by construction; `validateContinuity()` measures it anyway.
13	 */
14	import * as THREE from 'three';
15	
16	export type StageId = '01' | '02' | '03' | '04' | '05' | '06' | '07' | '08' | '09' | '10' | '11';
17	export type TubeKind = 'none' | 'chute' | 'gold' | 'perf';
18	export type StageProp = 'width' | 'tube' | 'speed' | 'bank';
19	
20	export interface StageDef {
21	  id: StageId;
22	  title: string;
23	  /** arc-length range on the course */
24	  s0: number;
25	  s1: number;
26	  /** water ribbon width (units) */
27	  width: number;
28	  /** enclosing tube radius (0 = open environment such as a drum/basin/chamber) */
29	  tube: number;
30	  tubeKind: TubeKind;
31	  /** auto-propulsion speed (units / s) */
32	  speed: number;
33	  /** coin counter shown in the locked reference screenshot of this stage */
34	  refCoins: number;
35	  interactive: boolean;
36	  /** banking strength multiplier */
37	  bank: number;
38	}
39	
40	export interface CourseSample {
41	  s: number;
42	  pos: THREE.Vector3;
43	  tan: THREE.Vector3;
44	  up: THREE.Vector3;
45	  right: THREE.Vector3;
46	}
47	
48	export const STAGE_TITLES: Record<StageId, string> = {
49	  '01': 'INSIDE THE WASHING MACHINE',
50	  '02': 'WHIRLPOOL TUMBLE',
51	  '03': 'WHIRLPOOL TWIRL',
52	  '04': 'THROUGH THE FIVE ARROWS',
53	  '05': 'FLOW INTO THE CURRENT',
54	  '06': 'CREST THE RINSE ARCH',
55	  '07': 'DIVE THE WASHER TUBE',
56	  '08': 'FINAL SPIN CHAMBER',
57	  '09': 'RIDE THE FINAL WAVE',
58	  '10': 'SLIDE INTO HIDING',
59	  '11': 'SAFELY HOME',
60	};
61	
62	/** Fixed world anchors shared by environment builders (absolute coordinates). */
63	export const WORLD = {
64	  drumA: { center: new THREE.Vector3(0, 0, 0), radius: 5, zBack: -6.5, zDoor: 3.5, doorRadius: 3.2, waterY: -2.5 },
65	  basin: { center: new THREE.Vector3(2, -16, -19), rimRadius: 11.5, rimY: -10.6, drainRadius: 4.3, drainY: -20.2 },
66	  /** Final Spin Chamber (08–11): drum with axis along Z, door at the far (-Z) end */
67	  chamber: { center: new THREE.Vector3(12, -101.1, 0), radius: 13.5, zBack: -280, zDoor: -332, floorY: -113.6, doorRadius: 6.2 },
68	  platform: { center: new THREE.Vector3(12, -110.6, -325.0), radius: 6.2, topY: -110.6 },
69	  plunge: { topY: -52, bottomY: -113.6 },
70	};
71	
72	/** funnel surface height of the whirlpool basin as a function of radius from its axis */
73	export function funnelY(r: number): number {
74	  const b = WORLD.basin;
75	  const t = THREE.MathUtils.clamp((r - b.drainRadius * 0.6) / (b.rimRadius - b.drainRadius * 0.6), 0, 1);
76	  return b.drainY + (b.rimY - b.drainY) * Math.pow(t, 0.72);
77	}
78	
79	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
80	const smooth = (a: number, b: number, x: number) => {
81	  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
82	  return t * t * (3 - 2 * t);
83	};
84	
85	/**
86	 * A stretch whose tunnel axis is an exact straight line a→b (the stream winds inside it). The
87	 * course lies on the line at both ends of the stretch; tube.ts aligns the tunnel axis to it.
88	 */
89	export interface StraightAxis {
90	  /** arc-length range of the stretch on the course */
91	  s0: number;
92	  s1: number;
93	  a: THREE.Vector3;
94	  b: THREE.Vector3;
95	  /** stream-to-tunnel-bottom depth on the line (water sits this high in the tube) */
96	  floorDepth: number;
97	}
98	
99	interface RouteData {
100	  points: THREE.Vector3[];
101	  marks: Record<string, number>;
102	  straight: { from: string; to: string; a: THREE.Vector3; b: THREE.Vector3; floorDepth: number }[];
103	}
104	
105	/**
106	 * 05 current (ref 05): the tunnel is a straight line; the STREAM winds inside it. The meander is the
107	 * lateral (world +X) offset of the course centreline from that line, as a function of the distance
108	 * `u` along the line (0 … L05). It is applied to the route AFTER smoothPolyline, so it is exact (the
109	 * smoothing would shave ~25 % off the amplitude) and still C¹ at both ends (offset and slope → 0).
110	 *
111	 * Shape tuned against the reference's cyan core: a small first crest under Benny at the 05
112	 * checkpoint (u≈uCrest, offset a0 to the LEFT, heading parallel to the tunnel axis), then crests
113	 * that grow toward the far end (screen: Benny → (560,700) → (450,600) → (520,520) → VP).
114	 * Coins (gameplay/coins.ts) sit on this centreline (lat 0), so they wind with the same S.
115	 */
116	export const S05 = {
117	  /** length of the straight tunnel line (units) */
118	  L: 72,
119	  /** wavelength along the line (crest → crest of the same side) */
120	  lambda: 32,
121	  /** u of the first (left) crest, where Benny rides at the 05 checkpoint */
122	  uCrest: 14,
123	  /** crest amplitude at uCrest and at uCrest + 1.5 λ (linear growth in between) */
124	  a0: 0.45,
125	  a1: 1.85,
126	  /** half extent of the stream (|offset| + half width) in the current: fills the tube floor */
127	  extent: 6.0,
128	};
129	
130	/** lateral offset (units, + = world +X = rider's right when heading -Z) of the 05 stream from its tunnel line */
131	export function meander05(u: number): number {
132	  const { L, lambda, uCrest, a0, a1 } = S05;
133	  if (u <= 0 || u >= L) return 0;
134	  const grow = THREE.MathUtils.clamp((u - uCrest) / (1.5 * lambda), 0, 1);
135	  const amp = (a0 + (a1 - a0) * grow) * smooth(0, 10, u) * (1 - smooth(L - 12, L, u));
136	  return -amp * Math.cos((2 * Math.PI * (u - uCrest)) / lambda);
137	}
138	
139	/** Generates the dense control polyline of the route (absolute coordinates). */
140	function buildRoute(): RouteData {
141	  const pts: THREE.Vector3[] = [];
142	  const marks: Record<string, number> = {};
143	  const straight: RouteData['straight'] = [];
144	  const push = (p: THREE.Vector3) => {
145	    if (pts.length && p.distanceTo(pts[pts.length - 1]) < 0.25) return;
146	    pts.push(p);
147	  };
148	  const mark = (k: string) => (marks[k] = pts.length - 1);
149	  const seg = (n: number, f: (t: number) => THREE.Vector3, skipFirst = true) => {
150	    for (let i = skipFirst ? 1 : 0; i <= n; i++) push(f(i / n));
151	  };
152	
153	  // ---- 01: Benny hidden in the towel, drum A front-left floor (camera looks toward the door) ----
154	  const dA = WORLD.drumA;
155	  const hc = V(0, -0.4, 0); // swirl axis
156	  const th0 = Math.atan2(-2.0, 1.6);
157	  push(V(1.6, -2.4, -2.2));
158	  mark('01');
159	  // ---- 02: whirlpool tumble — helix around the drum axis toward the back drain ----
160	  const thEnd = -Math.PI / 2 - Math.PI * 2;
161	  seg(26, (t) => {
162	    const th = th0 + (thEnd - th0) * t;
163	    const r = 2.56 + (3.9 - 2.56) * smooth(0, 1, t);
164	    const z = -2.2 + (-5.4 + 2.2) * t;
165	    return V(hc.x + r * Math.cos(th), hc.y + r * Math.sin(th), z);
166	  });
167	  mark('02_drain');
168	  // chute from drum A back drain down into the whirlpool basin rim
169	  const b = WORLD.basin;
170	  const spiralStart = V(b.center.x - 9.6, funnelY(9.6) + 0.25, b.center.z);
171	  const c0 = pts[pts.length - 1].clone();
172	  const chuteCtrl = [c0, V(-0.6, -5.6, -7.6), V(-3.2, -7.8, -10.4), V(-6.6, -9.8, -14.2), spiralStart.clone().add(V(0, 0.15, 2.4))];
173	  const chute = new THREE.CatmullRomCurve3(chuteCtrl, false, 'centripetal');
174	  seg(14, (t) => chute.getPoint(t));
175	  push(spiralStart);
176	  mark('03');
177	  // ---- 03: whirlpool twirl — 3/4 inward turn down the funnel that dives into the drain CENTRE ----
178	  // decreasing angle from the -X side (θ=-π/2) round the far and right sides to the near (+Z) side;
179	  // r shrinks as (1-t)^1.6 so the last stretch heads radially inward = straight -Z into the drain hole.
180	  seg(60, (t) => {
181	    const th = -Math.PI / 2 - Math.PI * 1.5 * (1 - (1 - t) * (1 - t)); // angle eases out → radial finish
182	    const r = 9.6 * Math.pow(1 - t, 0.9);
183	    return V(b.center.x + r * Math.sin(th), funnelY(r) + 0.25, b.center.z + r * Math.cos(th));
184	  });
185	  mark('04');
186	  // ---- 04: five-arrow slide — steep straight drop (≈32°) inside the gold ring pipe ----
187	  const s4 = pts[pts.length - 1].clone();
188	  const pitch4 = THREE.MathUtils.degToRad(32);
189	  const d4 = V(0, -Math.sin(pitch4), -Math.cos(pitch4));
190	  // pull-down arc from the drain lip into the steep slide pitch
191	  const R4a = 9;
192	  seg(7, (t) => {
193	    const a = pitch4 * t;
194	    return s4.clone().add(V(0, -R4a * (1 - Math.cos(a)), -R4a * Math.sin(a)));
195	  });
196	  const s4b = pts[pts.length - 1].clone();
197	  seg(16, (t) => s4b.clone().addScaledVector(d4, 34 * t));
198	  // pull out of the slide into the horizontal current
199	  const s4c = pts[pts.length - 1].clone();
200	  const R4 = 12;
201	  seg(8, (t) => {
202	    const a = -pitch4 + pitch4 * t;
203	    return s4c.clone().add(V(0, R4 * (Math.cos(-pitch4) - Math.cos(a)), R4 * (Math.sin(-pitch4) - Math.sin(a))));
204	  });
205	  mark('05');
206	  // ---- 05: long STRAIGHT perforated current tube (ref 05: concentric rings, ONE vanishing point);
207	  // the wide stream winds in S-curves inside it. Here only the straight line s5 → s5+L05 (slight
208	  // descent) is laid; the lateral S-offset meander05(u) is added after smoothing (see the end of
209	  // buildRoute). Offset and slope vanish at both ends, so 04 and 06 join tangentially and s6 (hence
210	  // 06/07/plunge/08) is unchanged. tube.ts builds the 05 tunnel on the line.
211	  const s5 = pts[pts.length - 1].clone();
212	  const L05 = V(0, -3, -S05.L);
213	  // 48 points (1.5-unit spacing) as before: the junction smoothing, hence the 04/05 and 05/06 stage
214	  // boundaries and the 06 checkpoint, stay exactly where they were
215	  seg(48, (t) => s5.clone().addScaledVector(L05, t));
216	  straight.push({ from: '05', to: '06', a: s5.clone(), b: s5.clone().add(L05), floorDepth: 3.3 });
217	  mark('06');
218	  // ---- 06: rinse arch — rises ~12 units, crests, curls down and to the right into the 07 tube ----
219	  const s6 = pts[pts.length - 1].clone();
220	  seg(34, (t) =>
221	    V(
222	      s6.x - 4 * Math.sin(Math.PI * t) + (WORLD.chamber.center.x - s6.x) * smooth(0.4, 1, t),
223	      s6.y + 12.5 * Math.pow(Math.sin(Math.PI * Math.min(t / 0.82, 1)), 1.15) - 4.5 * smooth(0.5, 1, t),
224	      s6.z - 46 * t,
225	    ),
226	  );
227	  mark('07');
228	  // ---- 07: winding washer tube (the visible stretch) ----
229	  const s7 = pts[pts.length - 1].clone();
230	  seg(32, (t) =>
231	    V(s7.x + 3.2 * Math.sin(3 * Math.PI * t) * Math.sin(Math.PI * t), s7.y + (WORLD.plunge.topY - s7.y) * t, s7.z - 60 * t),
232	  );
233	  mark('07_plunge_top');
234	  // ---- 07: THE DEEP PLUNGE — pull-down arc, long -70° straight, pull-up arc into the 08 inlet ----
235	  const p0 = pts[pts.length - 1].clone();
236	  const R = 14;
237	  const amax = THREE.MathUtils.degToRad(70);
238	  seg(12, (t) => {
239	    const a = amax * t;
240	    return p0.clone().add(V(0, -R * (1 - Math.cos(a)), -R * Math.sin(a)));
241	  });
242	  const p1 = pts[pts.length - 1].clone();
243	  const dPl = V(0, -Math.sin(amax), -Math.cos(amax));
244	  // straight length chosen so the bottom lands exactly on the chamber floor altitude
245	  const drop = p0.y - WORLD.plunge.bottomY;
246	  const Lstraight = (drop - 2 * R * (1 - Math.cos(amax))) / Math.sin(amax);
247	  seg(Math.ceil(Lstraight / 2), (t) => p1.clone().addScaledVector(dPl, Lstraight * t));
248	  mark('07_plunge_mid_end');
249	  const p2 = pts[pts.length - 1].clone();
250	  seg(12, (t) => {
251	    const a = -amax + amax * t;
252	    return p2.clone().add(V(0, R * (Math.cos(-amax) - Math.cos(a)), R * (Math.sin(-amax) - Math.sin(a))));
253	  });
254	  mark('07_plunge_bottom');
255	  const p3 = pts[pts.length - 1].clone();
256	  const zIn = WORLD.chamber.zBack;
257	  seg(4, (t) => V(p3.x, p3.y, p3.z + (zIn - p3.z) * t));
258	  mark('08');
259	  // ---- 08–10: Final Spin Chamber — winding stream toward the platform & towel ----
260	  const s8 = pts[pts.length - 1].clone();
261	  const plat = WORLD.platform;
262	  seg(14, (t) => V(s8.x + 3.6 * Math.sin(2 * Math.PI * t) * Math.sin(Math.PI * t), s8.y, s8.z - 15 * t));
263	  mark('09');
264	  const s9 = pts[pts.length - 1].clone();
265	  seg(14, (t) => V(s9.x - 3.2 * Math.sin(Math.PI * t), s9.y + 0.1 * t, s9.z - 15 * t));
266	  mark('10');
267	  const s10 = pts[pts.length - 1].clone();
268	  const end = V(plat.center.x, plat.topY + 0.45, plat.center.z + 0.6);
269	  seg(10, (t) =>
270	    V(s10.x + (end.x - s10.x) * t, s10.y + (end.y - s10.y) * smooth(0.3, 1, t), s10.z + (end.z - s10.z) * t),
271	  );
272	  mark('11');
273	  smoothPolyline(pts, marks['03'], 2.2, 3);
274	  // 05 meander: exact lateral offset from the straight tunnel line (after smoothing, see S05)
275	  const dir05 = L05.clone().normalize();
276	  for (let i = marks['05'] + 1; i < marks['06']; i++) {
277	    const u = pts[i].clone().sub(s5).dot(dir05) * (S05.L / L05.length());
278	    pts[i].x += meander05(u);
279	  }
280	  return { points: pts, marks, straight };
281	}
282	
283	/**
284	 * Arc-length Gaussian smoothing of the polyline from index `from` to the end (endpoints fixed).
285	 * Removes tangent kinks where independently generated segments meet; the 02 tumble helix
286	 * (before `from`) is left untouched.
287	 */
288	function smoothPolyline(pts: THREE.Vector3[], from: number, sigma: number, passes: number) {
289	  for (let pass = 0; pass < passes; pass++) {
290	    const cum: number[] = [0];
291	    for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + pts[i].distanceTo(pts[i - 1]));
292	    const out = pts.map((p) => p.clone());
293	    for (let i = from + 1; i < pts.length - 1; i++) {
294	      const acc = new THREE.Vector3();
295	      let wsum = 0;
296	      for (let j = i - 12; j <= i + 12; j++) {
297	        if (j < from || j >= pts.length) continue;
298	        const d = cum[j] - cum[i];
299	        const w = Math.exp(-(d * d) / (2 * sigma * sigma));
300	        acc.addScaledVector(pts[j], w);
301	        wsum += w;
302	      }
303	      out[i].copy(acc.divideScalar(wsum));
304	    }
305	    for (let i = from + 1; i < pts.length - 1; i++) pts[i].copy(out[i]);
306	  }
307	}
308	
309	export class Course {
310	  readonly curve: THREE.CatmullRomCurve3;
311	  readonly length: number;
312	  readonly stages: StageDef[];
313	  readonly marks: Record<string, number>; // arc-length of named marks
314	  /** straight tunnel stretches (05 current) — see StraightAxis */
315	  readonly straightAxes: StraightAxis[];
316	  /** world X of the straight 05 tunnel line (the meander is pos.x − line05x) */
317	  private readonly line05x: number;
318	  private st05!: StageDef;
319	  private st10!: StageDef;
320	  private readonly N: number;
321	  private readonly ds: number;
322	  private readonly P: Float32Array;
323	  private readonly T: Float32Array;
324	  private readonly U: Float32Array;
325	
326	  constructor() {
327	    const route = buildRoute();
328	    this.curve = new THREE.CatmullRomCurve3(route.points, false, 'centripetal');
329	    // arc-length table over curve parameter u
330	    const M = route.points.length * 24;
331	    const us: number[] = [0];
332	    const ls: number[] = [0];
333	    let prev = this.curve.getPoint(0);
334	    for (let i = 1; i <= M; i++) {
335	      const u = i / M;
336	      const p = this.curve.getPoint(u);
337	      ls.push(ls[i - 1] + p.distanceTo(prev));
338	      us.push(u);
339	      prev = p;
340	    }
341	    this.length = ls[M];
342	    const uAtS = (s: number) => {
343	      let lo = 0, hi = M;
344	      while (hi - lo > 1) {
345	        const mid = (lo + hi) >> 1;
346	        if (ls[mid] < s) lo = mid; else hi = mid;
347	      }
348	      const f = (s - ls[lo]) / Math.max(1e-6, ls[hi] - ls[lo]);
349	      return us[lo] + (us[hi] - us[lo]) * f;
350	    };
351	    const sAtIndex = (i: number) => {
352	      const u = i / (route.points.length - 1);
353	      const k = Math.round(u * M);
354	      return ls[k];
355	    };
356	    this.marks = {};
357	    for (const [k, i] of Object.entries(route.marks)) this.marks[k] = sAtIndex(i);
358	    this.straightAxes = route.straight.map((r) => ({ s0: this.marks[r.from], s1: this.marks[r.to], a: r.a, b: r.b, floorDepth: r.floorDepth }));
359	    this.line05x = route.straight[0].a.x;
360	
361	    // ---- stages ----
362	    const m = this.marks;
363	    const def = (id: StageId, s0: number, s1: number, o: Partial<StageDef>): StageDef => ({
364	      id, title: STAGE_TITLES[id], s0, s1, width: 5, tube: 0, tubeKind: 'none', speed: 11, refCoins: 0,
365	      interactive: true, bank: 1, ...o,
366	    });
367	    this.stages = [
368	      def('01', 0, 0.01, { width: 6, interactive: false, speed: 0 }),
369	      def('02', 0.01, m['03'], { width: 5, interactive: false, speed: 9, bank: 0 }),
370	      def('03', m['03'], m['04'], { width: 7, speed: 9, refCoins: 1330, bank: 2.2 }),
371	      def('04', m['04'], m['05'], { width: 4.4, tube: 4.8, tubeKind: 'gold', speed: 14, refCoins: 1330 }),
372	      // 05: level current (ref 05 shows no tilt) → weak curvature banking. `width` is the hand-over
373	      // value at the 04/06 junctions; inside the current widthAt() widens the stream to fill the floor.
374	      def('05', m['05'], m['06'], { width: 9, tube: 7.6, tubeKind: 'perf', speed: 11, refCoins: 1420, bank: 0.25 }),
375	      def('06', m['06'], m['07'], { width: 7, tube: 15, tubeKind: 'perf', speed: 11, refCoins: 1680, bank: 0.6 }),
376	      def('07', m['07'], m['08'], { width: 5.6, tube: 7.2, tubeKind: 'perf', speed: 12, refCoins: 1940 }),
377	      def('08', m['08'], m['09'], { width: 4.8, speed: 9.5, refCoins: 2040 }),
378	      def('09', m['09'], m['10'], { width: 6.4, speed: 9.5, refCoins: 2280 }),
379	      def('10', m['10'], m['11'], { width: 3.8, speed: 7.5, refCoins: 2500 }),
380	      def('11', m['11'], this.length, { width: 3, interactive: false, speed: 0, refCoins: 2500 }),
381	    ];
382	
383	    // ---- dense frame table (pos, tangent, banked up) ----
384	    this.N = Math.ceil(this.length / 0.25) + 1;
385	    this.ds = this.length / (this.N - 1); // exact spacing so the last interval is not short
386	    this.P = new Float32Array(this.N * 3);
387	    this.T = new Float32Array(this.N * 3);
388	    this.U = new Float32Array(this.N * 3);
389	    const pos: THREE.Vector3[] = [];
390	    const tan: THREE.Vector3[] = [];
391	    for (let i = 0; i < this.N; i++) {
392	      const s = Math.min(this.length, i * this.ds);
393	      const u = uAtS(s);
394	      pos.push(this.curve.getPoint(u));
395	      tan.push(this.curve.getTangent(u).normalize());
396	    }
397	    // up: world-up projected off the tangent + curvature banking, then smoothed
398	    const WU = new THREE.Vector3(0, 1, 0);
399	    const ups: THREE.Vector3[] = [];
400	    let prevUp = WU.clone();
401	    for (let i = 0; i < this.N; i++) {
402	      const t = tan[i];
403	      let up = WU.clone().addScaledVector(t, -WU.dot(t));
404	      if (up.lengthSq() < 1e-4) up = prevUp.clone().addScaledVector(t, -prevUp.dot(t));
405	      up.normalize();
406	      // banking from lateral curvature
407	      const i0 = Math.max(0, i - 4), i1 = Math.min(this.N - 1, i + 4);
408	      const k = tan[i1].clone().sub(tan[i0]).divideScalar((i1 - i0) * this.ds);
409	      const right = new THREE.Vector3().crossVectors(t, up).normalize();
410	      const st = this.stageAtS(i * this.ds);
411	      const bankAngle = THREE.MathUtils.clamp(-k.dot(right) * 6 * st.bank, -0.85, 0.85);
412	      up.applyAxisAngle(t, bankAngle);
413	      ups.push(up);
414	      prevUp = up;
415	    }
416	    // smooth up vectors (box filter) & re-orthogonalize
417	    const sm: THREE.Vector3[] = ups.map((_, i) => {
418	      const acc = new THREE.Vector3();
419	      for (let j = -8; j <= 8; j++) acc.add(ups[THREE.MathUtils.clamp(i + j, 0, this.N - 1)]);
420	      const t = tan[i];
421	      return acc.addScaledVector(t, -acc.dot(t)).normalize();
422	    });
423	    for (let i = 0; i < this.N; i++) {
424	      pos[i].toArray(this.P, i * 3);
425	      tan[i].toArray(this.T, i * 3);
426	      sm[i].toArray(this.U, i * 3);
427	    }
428	    this.st05 = this.stage('05');
429	    this.st10 = this.stage('10');
430	    // '05_crest': the first meander crest (stream furthest left, heading parallel to the tunnel
431	    // axis) — the 05 QA checkpoint, where Benny faces the vanishing point down the straight tube
432	    let best = this.st05.s0 + S05.uCrest, dMin = Infinity;
433	    for (let s = this.st05.s0 + 4; s < this.st05.s0 + S05.uCrest + S05.lambda / 4; s += 0.05) {
434	      const d = this.offset05(s);
435	      if (d < dMin) { dMin = d; best = s; }
436	    }
437	    this.marks['05_crest'] = best;
438	  }
439	
440	  /** 05 current: lateral offset (units, +X) of the stream centreline from the straight tunnel line */
441	  offset05(s: number): number {
442	    const st = this.st05;
443	    if (s <= st.s0 || s >= st.s1) return 0;
444	    return this.sample(s).pos.x - this.line05x;
445	  }
446	
447	  stageAtS(s: number): StageDef {
448	    for (const st of this.stages) if (s < st.s1) return st;
449	    return this.stages[this.stages.length - 1];
450	  }
451	
452	  stage(id: StageId): StageDef {
453	    return this.stages.find((s) => s.id === id)!;
454	  }
455	
456	  /**
457	   * smoothly blended per-stage property (blend ±blend units around stage boundaries).
458	   * Accepts either argument order: prop(s, 'width') or prop('width', s).
459	   */
460	  prop(s: number, key: StageProp, blend?: number): number;
461	  prop(key: StageProp, s: number, blend?: number): number;
462	  prop(a: number | StageProp, b: number | StageProp, blend = 6): number {
463	    const s = (typeof a === 'number' ? a : b) as number;
464	    const key = (typeof a === 'string' ? a : b) as StageProp;
465	    let v = 0, w = 0;
466	    for (const st of this.stages) {
467	      const a = smooth(st.s0 - blend, st.s0 + blend, s) * (1 - smooth(st.s1 - blend, st.s1 + blend, s));
468	      if (a > 0) { v += st[key] * a; w += a; }
469	    }
470	    return w > 0 ? v / w : this.stageAtS(s)[key];
471	  }
472	
473	  widthAt(s: number): number {
474	    let base = this.prop(s, 'width');
475	    // 05 current (ref 05): the water fills the tube floor wall to wall. The centreline winds by
476	    // offset05(s), so the half width is S05.extent − |offset| (smooth abs): the outer edge of each bend
477	    // stays on the same tube chord (constant tunnel radius/depth in tube.ts) and the inner side of a
478	    // bend leaves a narrow bank for the foam, like a river.
479	    const st5 = this.st05;
480	    const k = smooth(st5.s0 + 0.5, st5.s0 + 10, s) * (1 - smooth(st5.s1 - 10, st5.s1 - 0.5, s));
481	    if (k > 0) {
482	      const d = this.offset05(s);
483	      base += (2 * (S05.extent - Math.sqrt(d * d + 0.09)) - base) * k;
484	    }
485	    // the stream narrows into the towel opening at the very end of 10
486	    const st10 = this.st10;
487	    return base * (1 - 0.35 * smooth(st10.s1 - 8, st10.s1, s));
488	  }
489	
490	  sample(s: number, out?: CourseSample): CourseSample {
491	    const o = out ?? { s: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3(), up: new THREE.Vector3(), right: new THREE.Vector3() };
492	    const x = THREE.MathUtils.clamp(s, 0, this.length) / this.ds;
493	    const i = Math.min(this.N - 2, Math.floor(x));
494	    const f = x - i;
495	    const lerp3 = (A: Float32Array, v: THREE.Vector3) =>
496	      v.set(
497	        A[i * 3] + (A[i * 3 + 3] - A[i * 3]) * f,
498	        A[i * 3 + 1] + (A[i * 3 + 4] - A[i * 3 + 1]) * f,
499	        A[i * 3 + 2] + (A[i * 3 + 5] - A[i * 3 + 2]) * f,
500	      );
501	    o.s = s;
502	    lerp3(this.P, o.pos);
503	    lerp3(this.T, o.tan).normalize();
504	    lerp3(this.U, o.up);
505	    o.up.addScaledVector(o.tan, -o.up.dot(o.tan)).normalize();
506	    o.right.crossVectors(o.tan, o.up).normalize();
507	    return o;
508	  }
509	
510	  /** world position on the water at arc-length s with lateral offset (− left, + right) and height */
511	  pointAt(s: number, lateral = 0, height = 0, out = new THREE.Vector3()): THREE.Vector3 {
512	    const f = this.sample(s);
513	    return out.copy(f.pos).addScaledVector(f.right, lateral).addScaledVector(f.up, height);
514	  }
515	}
516	
517	export interface ContinuityReport {
518	  ok: boolean;
519	  boundaries: { from: StageId; to: StageId; s: number; posGap: number; tangentAngleDeg: number; upAngleDeg: number; altitude: number }[];
520	  maxStepTangentDeg: number;
521	  maxStepPos: number;
522	  plunge: { entryAltitude07: number; plungeTop: { s: number; y: number }; plungeMid: { s: number; y: number }; plungeBottom: { s: number; y: number }; inlet08: { s: number; y: number }; verticalDrop: number; minPitchDeg: number };
523	}
524	
525	/** Numerical continuity validation of the whole route. */
526	export function validateContinuity(c: Course): ContinuityReport {
527	  const eps = 0.02;
528	  const boundaries = c.stages.slice(0, -1).map((st, i) => {
529	    const nx = c.stages[i + 1];
530	    const sa = Math.max(st.s1 - eps, 0);
531	    const sb = Math.min(st.s1 + eps, c.length); // 11 starts at the route end (cinematic)
532	    const a = c.sample(sa);
533	    const b = c.sample(sb);
534	    return {
535	      from: st.id,
536	      to: nx.id,
537	      s: +st.s1.toFixed(2),
538	      posGap: +(a.pos.distanceTo(b.pos) - (sb - sa)).toFixed(4),
539	      tangentAngleDeg: +THREE.MathUtils.radToDeg(a.tan.angleTo(b.tan)).toFixed(3),
540	      upAngleDeg: +THREE.MathUtils.radToDeg(a.up.angleTo(b.up)).toFixed(3),
541	      altitude: +a.pos.y.toFixed(2),
542	    };
543	  });
544	  let maxT = 0, maxP = 0;
545	  const step = 0.25;
546	  let prev = c.sample(0);
547	  let minPitch = 0;
548	  const rideStart = c.stage('03').s0; // 01–02 tumble helix is a cinematic, checked for gaps only
549	  for (let s = step; s <= c.length; s += step) {
550	    const cur = c.sample(s);
551	    if (s > rideStart + step) maxT = Math.max(maxT, THREE.MathUtils.radToDeg(prev.tan.angleTo(cur.tan)));
552	    maxP = Math.max(maxP, prev.pos.distanceTo(cur.pos));
553	    if (s > c.marks['07_plunge_top'] && s < c.marks['08']) minPitch = Math.min(minPitch, THREE.MathUtils.radToDeg(Math.asin(cur.tan.y)));
554	    prev = { ...cur, pos: cur.pos.clone(), tan: cur.tan.clone(), up: cur.up.clone(), right: cur.right.clone() };
555	  }
556	  const y = (s: number) => +c.sample(s).pos.y.toFixed(2);
557	  const top = c.marks['07_plunge_top'];
558	  const bottom = c.marks['07_plunge_bottom'];
559	  const mid = (top + bottom) / 2;
560	  const inlet = c.marks['08'];
561	  const plunge = {
562	    entryAltitude07: y(c.stage('07').s0),
563	    plungeTop: { s: +top.toFixed(2), y: y(top) },
564	    plungeMid: { s: +mid.toFixed(2), y: y(mid) },
565	    plungeBottom: { s: +bottom.toFixed(2), y: y(bottom) },
566	    inlet08: { s: +inlet.toFixed(2), y: y(inlet) },
567	    verticalDrop: +(y(top) - y(inlet)).toFixed(2),
568	    minPitchDeg: +minPitch.toFixed(1),
569	  };
570	  const ok =
571	    boundaries.every((b) => Math.abs(b.posGap) < 0.01 && b.tangentAngleDeg < 1 && b.upAngleDeg < 2) &&
572	    maxP < step * 1.05 &&
573	    maxT < 8 && // ≥1.8-unit turn radius anywhere on the ride (tightest: the drop into the 03 drain)
574	    plunge.verticalDrop > 50 &&
575	    plunge.inlet08.y < plunge.entryAltitude07 - 50;
576	  return { ok, boundaries, maxStepTangentDeg: +maxT.toFixed(3), maxStepPos: +maxP.toFixed(4), plunge };
577	}
