1	/**
2	 * Third-person ride camera: behind/above Benny, looking along his heading (the course tangent), or
3	 * along the straight tunnel axis inside the 05–07 tube so the gold rings converge to one vanishing point
4	 * as in the references. Pitch & roll follow the banked path smoothly — including the 07 plunge.
5	 */
6	import * as THREE from 'three';
7	import { WORLD } from '../world/course';
8	import type { Course, StageId } from '../world/course';
9	import type { TubePath } from '../world/tube';
10	
11	export interface CamParams {
12	  back: number; // distance behind Benny
13	  up: number; // height above Benny's water point
14	  ahead: number; // look-at distance ahead
15	  lookUp: number; // look-at height
16	  fov: number;
17	  latFollow: number; // 1 = camera fully follows Benny's lateral offset
18	  roll: number; // 0..1 how much of the path bank the camera adopts
19	  /** 05 only: view yaw (deg) to the LEFT of the tunnel axis, i.e. the vanishing point sits right of centre */
20	  yaw?: number;
21	  /** 05 only: lateral dead zone (units): the camera holds the tunnel axis while Benny is within ~this of it */
22	  deadZone?: number;
23	}
24	
25	export const STAGE_CAM: Partial<Record<StageId, CamParams>> = {
26	  '03': { back: 6.5, up: 6.5, ahead: 6, lookUp: -1.5, fov: 64, latFollow: 0.3, roll: 0.3 },
27	  '04': { back: 8.5, up: 5.2, ahead: 14, lookUp: -3.0, fov: 66, latFollow: 0.6, roll: 0.4 },
28	  // 05: level rear chase down the straight current tube, camera ON the tunnel axis (rings concentric).
29	  // Ref 05 measured at vFOV 62: VP (498, 479) → view pitched atan((up-lookUp)/(ahead+back)) ≈ 12.7°
30	  // below and yawed ≈ 3° left of the axis; Benny's waterline 711 px below the VP → up/back ≈ 0.56.
31	  '05': { back: 6.4, up: 3.6, ahead: 18, lookUp: -1.92, fov: 62, latFollow: 0.85, roll: 0, yaw: 2.96, deadZone: 1.0 },
32	  '06': { back: 5.6, up: 2.6, ahead: 12, lookUp: 3.4, fov: 66, latFollow: 0.7, roll: 0.4 },
33	  '07': { back: 6.4, up: 4.1, ahead: 18, lookUp: 1.8, fov: 62, latFollow: 0.6, roll: 0.6 },
34	  '08': { back: 6.2, up: 3.7, ahead: 16, lookUp: 0.2, fov: 62, latFollow: 0.8, roll: 0.3 },
35	  '09': { back: 6.2, up: 3.7, ahead: 15, lookUp: 0.6, fov: 62, latFollow: 0.8, roll: 0.3 },
36	  '10': { back: 5.8, up: 3.4, ahead: 11, lookUp: 1.2, fov: 62, latFollow: 0.8, roll: 0.2 },
37	};
38	
39	const KEYS: (keyof CamParams)[] = ['back', 'up', 'ahead', 'lookUp', 'fov', 'latFollow', 'roll'];
40	
41	export function camParamsAt(course: Course, s: number, blend = 8): CamParams {
42	  const acc: CamParams = { back: 0, up: 0, ahead: 0, lookUp: 0, fov: 0, latFollow: 0, roll: 0 };
43	  let w = 0;
44	  for (const st of course.stages) {
45	    const p = STAGE_CAM[st.id];
46	    if (!p) continue;
47	    const a = THREE.MathUtils.smoothstep(s, st.s0 - blend, st.s0 + blend) * (1 - THREE.MathUtils.smoothstep(s, st.s1 - blend, st.s1 + blend));
48	    if (a <= 0) continue;
49	    for (const k of KEYS) acc[k] += p[k] * a;
50	    w += a;
51	  }
52	  if (w === 0) return { ...(STAGE_CAM['03'] as CamParams) };
53	  for (const k of KEYS) acc[k] /= w;
54	  return acc;
55	}
56	
57	export class RideCamera {
58	  readonly pos = new THREE.Vector3();
59	  readonly target = new THREE.Vector3();
60	  readonly up = new THREE.Vector3(0, 1, 0);
61	  fov = 70;
62	  private init = false;
63	  /** optional straight tunnel axis + the s-range where the camera aligns to it */
64	  axis: { path: TubePath; s0: number; s1: number } | null = null;
65	
66	  constructor(private course: Course) {}
67	
68	  /** desired pose for Benny at (s, lateral) */
69	  desired(s: number, lat: number, outPos: THREE.Vector3, outTarget: THREE.Vector3, outUp: THREE.Vector3): CamParams {
70	    const p = camParamsAt(this.course, s);
71	    const f = this.course.sample(s);
72	    const fb = this.course.sample(Math.max(0, s - p.back * 0.5)); // smoothing of heading
73	    const dir = f.tan.clone().lerp(fb.tan, 0.35).normalize();
74	    let up = f.up.clone();
75	    if (this.axis) {
76	      const a = this.axis;
77	      const w = THREE.MathUtils.smoothstep(s, a.s0, a.s0 + 10) * (1 - THREE.MathUtils.smoothstep(s, a.s1 - 10, a.s1));
78	      if (w > 0) {
79	        const af = a.path.frame(s);
80	        dir.lerp(af.tan, w).normalize();
81	        up.lerp(af.up, w).normalize();
82	      }
83	    }
84	    up.addScaledVector(dir, -up.dot(dir)).normalize();
85	    const right = new THREE.Vector3().crossVectors(dir, up).normalize();
86	    const benny = f.pos.clone().addScaledVector(f.right, lat);
87	    const anchor = benny.clone().addScaledVector(right, -lat * (1 - p.latFollow));
88	    // offsets use an 'upright' up: banking only tilts the camera as much as `roll` allows
89	    const upPos = new THREE.Vector3(0, 1, 0).lerp(up, Math.max(p.roll, Math.abs(dir.y))).normalize();
90	    // position: ON the curved course behind Benny (stays inside bending/pitching tubes, e.g. the
91	    // 07 pull-up arc); aim: along his heading so he stays centred in winding streams
92	    const fbk = this.course.sample(Math.max(0, s - p.back));
93	    const upB = new THREE.Vector3(0, 1, 0).lerp(fbk.up, Math.max(p.roll, Math.abs(fbk.tan.y))).normalize();
94	    const straightPos = anchor.clone().addScaledVector(dir, -p.back).addScaledVector(upPos, p.up);
95	    const curvedPos = fbk.pos.clone().addScaledVector(fbk.right, lat * p.latFollow).addScaledVector(upB, p.up);
96	    // use the curved position where the path bends in pitch (plunge arcs), straight elsewhere
97	    const pitchBend = THREE.MathUtils.clamp(Math.abs(fbk.tan.y - f.tan.y) * 6, 0, 1);
98	    outPos.copy(straightPos).lerp(curvedPos, Math.max(pitchBend, 0.35));
99	    outTarget.copy(anchor).addScaledVector(dir, p.ahead).addScaledVector(upPos, p.lookUp);
100	    outUp.set(0, 1, 0).lerp(up, p.roll).normalize();
101	    // 03 whirlpool: dynamic high angle from the near side, looking down into the vortex toward the
102	    // drain and the porthole wall (Benny left, drain lower-right as in the reference)
103	    const st3 = this.course.stage('03');
104	    const w3 = THREE.MathUtils.smoothstep(s, st3.s0 - 6, st3.s0 + 2) * (1 - THREE.MathUtils.smoothstep(s, st3.s1 - 6, st3.s1 + 1));
105	    if (w3 > 0) {
106	      const B = WORLD.basin;
107	      const wp = benny.clone().add(new THREE.Vector3(2.8, 3.6, 5.6));
108	      const drain = new THREE.Vector3(B.center.x, B.drainY, B.center.z);
109	      const wt = benny.clone().lerp(drain, 0.2).add(new THREE.Vector3(0.6, -1.0, -2.4));
110	      outPos.lerp(wp, w3);
111	      outTarget.lerp(wt, w3);
112	      outUp.lerp(new THREE.Vector3(0, 1, 0), w3).normalize();
113	    }
114	    // 05 straight current tube: the '05' preset measured in the straight tunnel's own frame — aimed
115	    // along the tunnel axis (not Benny's S-curve heading) so the gold rings stay concentric on ONE
116	    // vanishing point, level (no roll). Laterally the camera rides the tunnel axis while Benny is near
117	    // it and eases toward him (latFollow) only as he swings wide (Gaussian dead zone), so the rings
118	    // stay concentric on the ref composition and Benny never leaves the frame when steering.
119	    const st5 = this.course.stage('05');
120	    const p5 = STAGE_CAM['05'] as CamParams;
121	    const w5 = this.axis ? THREE.MathUtils.smoothstep(s, st5.s0 + 1, st5.s0 + 8) * (1 - THREE.MathUtils.smoothstep(s, st5.s1 - 9, st5.s1 - 1)) : 0;
122	    if (w5 > 0 && this.axis) {
123	      const af = this.axis.path.frame(s);
124	      const T = af.tan.clone();
125	      const U = new THREE.Vector3(0, 1, 0).addScaledVector(T, -T.y).normalize();
126	      const Rt = new THREE.Vector3().crossVectors(T, U).normalize();
127	      const water = f.pos.clone().addScaledVector(f.right, lat); // Benny's point on the stream
128	      const off = water.clone().sub(af.pos).dot(Rt); // his lateral offset from the tunnel axis
129	      const dz = p5.deadZone ?? 1;
130	      const follow = p5.latFollow * (1 - Math.exp(-(off * off) / (dz * dz)));
131	      const cp = water.addScaledVector(T, -p5.back).addScaledVector(U, p5.up).addScaledVector(Rt, -off * (1 - follow));
132	      const pitch = Math.atan2(p5.up - p5.lookUp, p5.ahead + p5.back);
133	      const yaw = THREE.MathUtils.degToRad(p5.yaw ?? 0);
134	      const look = T.clone().multiplyScalar(Math.cos(pitch) * Math.cos(yaw)).addScaledVector(U, -Math.sin(pitch)).addScaledVector(Rt, -Math.cos(pitch) * Math.sin(yaw));
135	      outPos.lerp(cp, w5);
136	      outTarget.lerp(cp.clone().addScaledVector(look, p5.ahead + p5.back), w5);
137	      outUp.lerp(U, w5).normalize();
138	    }
139	    return p;
140	  }
141	
142	  update(dt: number, s: number, lat: number, cam: THREE.PerspectiveCamera, snap = false) {
143	    const dp = new THREE.Vector3(), dt3 = new THREE.Vector3(), du = new THREE.Vector3();
144	    const p = this.desired(s, lat, dp, dt3, du);
145	    const k = snap || !this.init ? 1 : 1 - Math.exp(-dt * 7);
146	    const kt = snap || !this.init ? 1 : 1 - Math.exp(-dt * 9);
147	    this.pos.lerp(dp, k);
148	    this.target.lerp(dt3, kt);
149	    this.up.lerp(du, kt).normalize();
150	    this.fov += (p.fov - this.fov) * (snap || !this.init ? 1 : Math.min(1, dt * 3));
151	    this.init = true;
152	    cam.position.copy(this.pos);
153	    cam.up.copy(this.up);
154	    cam.lookAt(this.target);
155	    if (Math.abs(cam.fov - this.fov) > 0.01) { cam.fov = this.fov; cam.updateProjectionMatrix(); }
156	  }
157	}
