1	/**
2	 * Gold $ coins anchored to the course (s, lateral, height). Real pickups: distance test against
3	 * Benny each frame; collected coins pop + sparkle and the counter increments by COIN_VALUE.
4	 * Layout follows the coin trails visible in the references (03 spiral trail, 04 left edge,
5	 * 05/07 snaking centre line, 06 on the arch crest, 08–10 toward the towel).
6	 */
7	import * as THREE from 'three';
8	import type { Course, StageId } from '../world/course';
9	import { canvasTexture } from '../world/materials';
10	
11	export const COIN_VALUE = 10;
12	
13	export interface CoinDef { s: number; lat: number; h: number; stage: StageId }
14	
15	export function coinLayout(course: Course): CoinDef[] {
16	  const out: CoinDef[] = [];
17	  const add = (stage: StageId, s: number, lat: number, h = 0.9) => out.push({ s, lat, h, stage });
18	  const st = (id: StageId) => course.stage(id);
19	  // 03 — spiral trail ahead of Benny toward the drain
20	  { const a = st('03'); for (let i = 0; i < 9; i++) add('03', a.s0 + 6 + i * 2.7, 0.9 - i * 0.12); }
21	  // 04 — along the left edge of the slide
22	  { const a = st('04'); for (let i = 0; i < 8; i++) add('04', a.s0 + 9 + i * 3.6, -1.35); }
23	  // 05 — snaking centre line
24	  { const a = st('05'); const n = 18; for (let i = 0; i < n; i++) { const s = a.s0 + 8 + i * ((a.s1 - a.s0 - 12) / n); add('05', s, 1.2 * Math.sin(i * 0.55)); } }
25	  // 06 — up and over the crest (left of centre like the ref)
26	  { const a = st('06'); const n = 18; for (let i = 0; i < n; i++) { const s = a.s0 + 4 + i * ((a.s1 - a.s0 - 6) / n); add('06', s, -1.3 + 0.7 * Math.sin(i * 0.4)); } }
27	  // 07 — winding trail, continuing down the plunge
28	  { const a = st('07'); const n = 24; for (let i = 0; i < n; i++) { const s = a.s0 + 6 + i * ((a.s1 - a.s0 - 10) / n); add('07', s, 1.0 * Math.sin(i * 0.5 + 1)); } }
29	  // 08 — S toward the platform
30	  { const a = st('08'); for (let i = 0; i < 8; i++) add('08', a.s0 + 3 + i * 1.9, -0.6 + 0.9 * Math.sin(i * 0.8)); }
31	  // 09 — arc along the left (inside of the bend, under the wave)
32	  { const a = st('09'); for (let i = 0; i < 9; i++) add('09', a.s0 + 1.5 + i * 1.7, -1.7 + i * 0.12); }
33	  // 10 — straight line into the towel tunnel
34	  { const a = st('10'); for (let i = 0; i < 5; i++) add('10', a.s0 + 1.5 + i * 2.0, -0.15); }
35	  return out;
36	}
37	
38	export interface CoinSystem {
39	  group: THREE.Group;
40	  defs: CoinDef[];
41	  collected: Uint8Array;
42	  /** returns number of coins picked up this frame */
43	  update(time: number, dt: number, bennyS: number, bennyLat: number): number;
