48	export function createCoins(course: Course): CoinSystem {
49	  const defs = coinLayout(course);
50	  const faceTex = canvasTexture(256, 256, (c, w, h) => {
51	    const g = c.createRadialGradient(w * 0.38, h * 0.32, 10, w / 2, h / 2, w * 0.55);
52	    g.addColorStop(0, '#fffbd8');
53	    g.addColorStop(0.5, '#ffdc3a');
54	    g.addColorStop(1, '#f0a400');
55	    c.fillStyle = g;
56	    c.beginPath(); c.arc(w / 2, h / 2, w / 2, 0, Math.PI * 2); c.fill();
57	    c.strokeStyle = '#ffe680'; c.lineWidth = 10;
58	    c.beginPath(); c.arc(w / 2, h / 2, w * 0.38, 0, Math.PI * 2); c.stroke();
59	    c.font = '800 170px "Baloo 2", Arial Black, sans-serif';
60	    c.textAlign = 'center'; c.textBaseline = 'middle';
61	    c.fillStyle = '#c47800';
62	    c.fillText('$', w / 2 + 4, h / 2 + 12);
63	    c.fillStyle = '#fff1a8';
64	    c.fillText('$', w / 2 - 2, h / 2 + 6);
65	  });
66	  const geo = new THREE.CylinderGeometry(0.5, 0.5, 0.14, 40, 1);
67	  geo.rotateX(Math.PI / 2); // faces along ±Z
68	  const side = new THREE.MeshStandardMaterial({ color: '#ffd23c', metalness: 0.9, roughness: 0.22, emissive: '#d08a00', emissiveIntensity: 0.55 });
69	  const face = new THREE.MeshStandardMaterial({ map: faceTex, metalness: 0.55, roughness: 0.3, emissive: '#ffffff', emissiveIntensity: 0.55, emissiveMap: faceTex });
70	  const mesh = new THREE.InstancedMesh(geo, [side, face, face], defs.length);
71	  mesh.frustumCulled = false;
72	  const group = new THREE.Group();
73	  group.name = 'coins';
74	  group.add(mesh);
75	  const collected = new Uint8Array(defs.length);
76	  const popT = new Float32Array(defs.length).fill(-1);
77	  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), basis = new THREE.Matrix4();
78	  const p = new THREE.Vector3(), sc = new THREE.Vector3();
79	  const spin = new THREE.Quaternion(), axis = new THREE.Vector3();
80	  const back = new THREE.Vector3();
81	
82	  const place = (time: number) => {
83	    defs.forEach((d, i) => {
84	      const f = course.sample(d.s);
85	      let scale = 1;
86	      if (collected[i]) {
87	        if (popT[i] < 0) { sc.setScalar(0); m.compose(p.set(0, -9999, 0), q.identity(), sc); mesh.setMatrixAt(i, m); return; }
88	        const k = THREE.MathUtils.clamp((time - popT[i]) / 0.35, 0, 1);
89	        if (k >= 1) { popT[i] = -1; sc.setScalar(0); m.compose(p.set(0, -9999, 0), q.identity(), sc); mesh.setMatrixAt(i, m); return; }
90	        scale = 1 + k * 0.8;
91	        p.copy(f.pos).addScaledVector(f.right, d.lat).addScaledVector(f.up, d.h + k * 1.6);
92	      } else {
93	        p.copy(f.pos).addScaledVector(f.right, d.lat).addScaledVector(f.up, d.h + 0.08 * Math.sin(time * 3 + i));
94	      }
95	      back.copy(f.tan).negate();
96	      const right = new THREE.Vector3().crossVectors(f.up, back).normalize();
97	      basis.makeBasis(right, f.up, back);
98	      q.setFromRotationMatrix(basis);
99	      spin.setFromAxisAngle(axis.set(0, 1, 0), 0.35 * Math.sin(time * 2.2 + i * 0.7));
100	      q.multiply(spin);
101	      m.compose(p, q, sc.setScalar(scale * (collected[i] ? 1 - (time - popT[i]) / 0.35 : 1)));
102	      mesh.setMatrixAt(i, m);
103	    });
104	    mesh.instanceMatrix.needsUpdate = true;
105	  };
106	  place(0);
107	
108	  return {
109	    group,
110	    defs,
111	    collected,
112	    update(time, _dt, s, lat) {
113	      let picked = 0;
114	      for (let i = 0; i < defs.length; i++) {
115	        if (collected[i]) continue;
116	        const d = defs[i];
117	        const ds = d.s - s;
118	        if (ds < -2 || ds > 2) continue;
119	        if (Math.abs(ds) < 1.0 && Math.abs(d.lat - lat) < 1.25) {
120	          collected[i] = 1;
121	          popT[i] = time;
122	          picked++;
123	        }
124	      }
125	      place(time);
126	      return picked;
127	    },
128	    resetUntil(s) {
129	      for (let i = 0; i < defs.length; i++) { collected[i] = defs[i].s < s ? 1 : 0; popT[i] = -1; }
130	      place(0);
131	    },
132	  };
133	}
